#include "audit_arithmetic.hpp"
int main(int argc,char** argv){try{
    using namespace audit;
    require(argc==4,"usage: identity_tangent BASELINE.json MODEL.json OUTPUT.json");auto data=read_json(argv[1]),model=read_json(argv[2]);std::vector<Term> terms;for(const auto& item:model.at("terms").arr){const auto& e=item.at("exponents").arr;require(e[0].integer()+e[1].integer()+e[2].integer()==4,"quartic degree");terms.push_back({e[0].integer(),e[1].integer(),Big(item.at("coefficient").scalar)});}int index=-1;for(size_t i=0;i<data.at("images").arr.size();++i)if(read_point(data.at("images").arr[i].at("point")).zero){require(index<0,"unique frozen identity image");index=int(i);}require(index>=0,"identity point exists");const auto& point=data.at("pool").at("points").arr.at(size_t(index));CP origin{Big(point.at("x").scalar),Big(point.at("y").scalar)};require(evaluate(terms,origin)==0,"identity lift on curve");Big dx=evaluate(terms,origin,1,0),dy=evaluate(terms,origin,0,1);auto l=normalize({dx,dy,mod(-dx*origin.x-dy*origin.y)});Poly restriction(5);for(const auto& term:terms){auto q=product(ppow({origin.x,l[1]},term.x),ppow({origin.y,mod(-l[0])},term.y));for(size_t i=0;i<q.size();++i)restriction[i]=mod(restriction[i]+term.c*q[i]);}trim(restriction);require(restriction.size()>2,"noncomponent tangent degree");auto residual=divide(divide(restriction,0),0);require(product({0,0,1},residual)==restriction,"tangent product reconstruction");int controls=0;auto corrupt=restriction;corrupt[0]=mod(corrupt[0]+1);rejects([&]{divide(corrupt,0);});++controls;
    bool changed_root_checked=false;for(int candidate=1;candidate<=4&&!changed_root_checked;++candidate)if(peval(restriction,candidate)!=0){rejects([&]{divide(restriction,candidate);});changed_root_checked=true;}require(changed_root_checked,"changed-root witness available");++controls;
    std::string category="affine-degree-exception";Big discriminant=0,legendre=0;bool independent=false;if(residual.size()==3){discriminant=mod(residual[1]*residual[1]-4*residual[0]*residual[2]);Big exponent=(p-1)/2;mpz_powm(legendre.get_mpz_t(),discriminant.get_mpz_t(),exponent.get_mpz_t(),p.get_mpz_t());auto aa=bn(discriminant),ee=bn(exponent),pp=bn(p),expected=bn(legendre);BN answer(BN_new());std::unique_ptr<BN_CTX,decltype(&BN_CTX_free)> context(BN_CTX_new(),BN_CTX_free);require(BN_mod_exp(answer.get(),aa.get(),ee.get(),pp.get(),context.get())==1&&BN_cmp(answer.get(),expected.get())==0,"independent discriminant Euler criterion");independent=true;category=legendre==0?"repeated-contact":legendre==1?"split-distinct-rational":"irreducible-quadratic";require(legendre==0||legendre==1||legendre==p-1,"Euler trichotomy");}
    std::ofstream out(argv[3]);require(bool(out),"fresh tangent output");out<<"{\"standing\":\"producer-unverified\",\"identity_point_index\":"<<index<<",\"category\":\""<<category<<"\",\"line\":";emit_poly(out,Poly(l.begin(),l.end()));out<<",\"restriction\":";emit_poly(out,restriction);out<<",\"residual\":";emit_poly(out,residual);out<<",\"discriminant\":\""<<discriminant<<"\",\"euler_criterion\":\""<<legendre<<"\",\"independent_modular_exponentiation_agrees\":"<<(independent?"true":"false")<<",\"corruptions_rejected\":"<<controls<<",\"new_curve_points\":0}\n";require(bool(out),"complete tangent output");
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
